head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gAcptNo;
scwin.gViewerStat = "P"; // 처리시 뷰=P,  조회시 뷰=R
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gSndlocTpCd;
scwin.gDate;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

scwin.vScrenID = 'ULDSTF10100.xml'; //책임자승인

scwin.search_yn = false;

//2023-03-17 KBoY 채권상장공시팀
//5분에 한번씩 미처리건이 있는지 확인용
scwin.isAlarm = true; //알람 상태가 on/off인지 체크 
scwin.isBondsTeam = false; //채권상장공시팀인지 체크
scwin.alarmCnt = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //30초에 한번 리로딩 되는데 5분에 한번을 체크하기위해 10으로 나누어 떨어지면 채권 알림체크하도록

scwin.fn_SetCode = function() {
    $c.stf.showObj(panel_2, false);
    $c.stf.showObj(panel_3, false); //공시구분은 시장운영팀만 보여준다.(2016.06.17)

    var strDepCd = js_dep_cd.substring(0, 2);
    //alert("strDepCd-->"+strDepCd); 

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 보여준다.
    //if (js_dep_cd.substring(0,2) == '26'  || js_dep_cd.substring(0,2) == '34' ) {
    //if (js_dep_cd.substring(0,1) == '2'  || js_dep_cd.substring(0,2) == '34' ) {
    if (strDepCd == '24' || strDepCd == '25' || strDepCd == '2B' || js_dep_cd == '11D0') {
        //24=채권상장, 25=상장심사부, 2B=증권상품
        $c.stf.showObj(panel_2, true);
    } else if (strDepCd == '26' || strDepCd == '34') {
        //공시팀인경우 당번만 보여준다 2013.03.26
        if (scwin.gDepCd == '2610' || scwin.gDepCd == '3410') {
            //공시제도팀의 경우 팀장, 팀원 모두 공시제도팀공시만 볼 수 있다. 20210312 - IT운영팀
            $c.stf.showObj(panel_2, false);
        } else {
            if (scwin.gJobTitle == '09' || scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') {
                $c.stf.showObj(panel_2, true);
            }
        }
    }
    if (strDepCd == '22' || strDepCd == '32') {
        //공시구분은 시장운영팀만 보여준다.(2016.06.17)
        $c.stf.showObj(panel_3, true);
    }
    if (js_dep_cd == '3220') {
        // 코스닥시장운영팀일땐 모두 선택 : 2008.09.04 수정
        chb_stat_all.setValue(1);
        chb_stat_00.setValue(1);
        chb_stat_02.setValue(1);
        chb_stat_01.setValue(1);
        chb_stat_10.setValue(1);
        chb_stat_20.setValue(1);
        chb_stat_30.setValue(1);
        chb_stat_40.setValue(1);
        chb_reg.setValue(1);
    }
    if (scwin.gLdMktTp == '1') {
        // 유가일때만 disabled="disabled"
        chb_stat_10.setDisabled("disabled");
        chb_stat_20.setDisabled("disabled");
    }

    // 현재날짜 셋팅	
    scwin.gDate = $c.ut.cGetToday("yyyymmdd");
    edt_SrchDay.setValue(scwin.gDate);

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_emp.Reset();
};
scwin.fn_DepListLoadComplete = function() {
    scwin.setAlarm();
    $c.stf.setObjectValue(cmb_TeamList, js_dep_cd);
    // 부서코드 가져온후에  초기검색
    scwin.fn_InitSearch();
};


// 화면 로딩시 디폴트 검색
scwin.fn_InitSearch = function() {
    //fn_Search();		
    scwin.fn_Reload('N');
};
scwin.fn_Reload = function(pReload) {
    fn_CheckCond(pReload);
    setTimeout("fn_Reload('Y')", 30000); // 1초 = 1000 , 30초 = 30000
    if (scwin.isBondsTeam && pReload == "Y") scwin.alarmCnt++;
    //		txt_test.value = alarmCnt;


    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !책임자승인--;
클릭-- > function(pReload) {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_SrchDay).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_SrchDay.focus();
        return;
    }
    var vStatCnt = 0;
    if (chb_stat_00.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_02.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_01.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_10.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_20.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_30.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_40.checked == true) {
        vStatCnt++;
    }
    if (chb_reg.checked == true) {
        vStatCnt++;
    }

    // 처리상태 1개 이상 체크
    if (vStatCnt < 1) {
        $c.win.alert("처리상태를 한개 이상  선택하시오.");
        chb_stat_00.focus();
        return;
    }
    scwin.gDate = $c.stf.getObjectValue(edt_SrchDay);

    // 유가 공시팀(26**), 코스닥 공시팀(34**) =>  선택부서로
    //if (js_dep_cd.substring(0,2) == '26'  || js_dep_cd.substring(0,2) == '34' ) {
    if (js_dep_cd.substring(0, 1) == '2' || js_dep_cd.substring(0, 2) == '34' || js_dep_cd == '11D0') {
        scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
        scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
    } else {
        scwin.gDepCd = ""; // 부서코드 없음 => 전체	
        scwin.gEmpNo = "";
    }
    fn_Search(pReload);
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !책임자승인--;
클릭-- > function(pReload) {
    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 시장구분을 '4'로 셋팅
    ******************************************************************/
    if (js_bond_yn == "Y") {
        scwin.gLdMktTp = "4";
    }
    $c.cm.ShowWin_yn(grd_Grid, scwin.search_yn);
    var url = "/DisclosureApproval.do?method=listDisclosureApproval&inputMessageId=DSCLSTUDYCOND_IN" + "&outputMessageId=DSCLSTUDYLIST_OUT" + "&ACPT_DATE=" + scwin.gDate + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + scwin.gLdMktTp + "&STAT_00=" + scwin.getChkValue(chb_stat_00) + "&STAT_02=" + scwin.getChkValue(chb_stat_02) + "&STAT_01=" + scwin.getChkValue(chb_stat_01) + "&STAT_10=" + scwin.getChkValue(chb_stat_10) + "&STAT_20=" + scwin.getChkValue(chb_stat_20) + "&STAT_30=" + scwin.getChkValue(chb_stat_30) + "&STAT_40=" + scwin.getChkValue(chb_stat_40) + "&STAT_REG=" + scwin.getChkValue(chb_reg) + "&UP_DEP_CD=" + js_belngdepcd + "&RSN_CLSS_CD=" + $c.stf.getObjectValue(rdo_discls);

    //alert('[pReload]'+pReload);
    if (pReload != 'Y') {
        //자동refresh일때는 로그 없앰
        url = url + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    }
    dts_DsclApprovalList.DataID = encodeURI(url);
    dts_DsclApprovalList.reset();
    /*
    var fFrame = frame.Provider("/pageIndex").selPageID;
    var fname = frame.FrameID;
    if (fFrame == fname) {
        ShowWin(grd_Grid);	
    }	
    */

};



// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclApprovalList.getCellData(eval(obj), "ACPT_NO");
    //gMainFormCd = dts_DsclApprovalList.NameString(eval(obj),"FORM_CD");
    //gFormVer = dts_DsclApprovalList.NameString(eval(obj),"FORM_VER");
    scwin.gIsurCd = dts_DsclApprovalList.getCellData(eval(obj), "ISUR_CD");
    //gSndlocTpCd = dts_DsclApprovalList.NameString(eval(obj),"SNDLOC_TP_CD");
    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd+","+ gSndlocTpCd);

};
scwin.fn_checkAll = function() {
    // 전체가 체크일때 
    if (chb_stat_all.checked == true) {
        chb_stat_00.setValue(1);
        chb_stat_02.setValue(1);
        chb_stat_01.setValue(1);
        chb_stat_10.setValue(1);
        chb_stat_20.setValue(1);
        chb_stat_30.setValue(1);
        chb_stat_40.setValue(1);
        chb_reg.setValue(1);
    } else {
        if (scwin.gLdMktTp == '1') {
            // 유가일때만 disabled="disabled"
            chb_stat_00.setValue(0);
            chb_stat_02.setValue(0);
            chb_stat_01.setValue(0);
            chb_stat_10.setValue(1);
            chb_stat_20.setValue(1);
            chb_stat_30.setValue(0);
            chb_stat_40.setValue(0);
            chb_reg.setValue(0);
        } else {
            chb_stat_00.setValue(0);
            chb_stat_02.setValue(0);
            chb_stat_01.setValue(0);
            chb_stat_10.setValue(0);
            chb_stat_20.setValue(0);
            chb_stat_30.setValue(0);
            chb_stat_40.setValue(0);
            chb_reg.setValue(0);
        }
    }
};




//23.03.17 KBoY 채권상장공시팀인경우 알림메세지 
scwin.setAlarm = function() {
    pnl_alert.style.display = 'none';
    if (js_dep_cd == "2430") scwin.isBondsTeam = true;
    if (scwin.isBondsTeam) {
        pnl_bonds.style.display = '';
        //pnl_alert.innerHTML = "<embed src='/common/untreated.wav' name='alertSound' autostart='false'>";
        pnl_alert.innerHTML = "<embed src='/common/bonds_untreated.wav' name='alertSound1' autostart='false'>" + "<embed src='/common/bonds_alert2.wav' name='alertSound2' autostart='false'>";
    } else {
        pnl_bonds.style.display = 'none';
    }
};
scwin.isFirstAlarm = true;
scwin.alarmCheck = function() {
    var isDup = false; //알림중복여부
    if (scwin.isAlarm) {
        //알람 on 상태			
        if (scwin.isExistedTodoJob()) {
            //미처리건이 있는 상태
            /*
				if(alarmCnt == 1){				
					var soundTimeout = setTimeout("playAlarm()", 3000);//이상하게 시작할땐 소리가 안나네. 3초 지연					
				}else if(alarmCnt%10 == 0){					
						if(isFirstAlarm){
							clearTimeout(soundTimeout);
//							txt_test.value = 'clear';
							isFirstAlarm = false;
						}	
						playAlarm();					
				}
				*/
            if (scwin.alarmCnt % 10 == 0) {
                isDup = true;
                if (scwin.alarmCnt == 0) {
                    var soundTimeout = setTimeout("playAlarm(1)", 3000); //이상하게 시작할땐 소리가 안나네. 3초 지연
                } else {
                    scwin.playAlarm(1);
                }
            }
        }

        //채권만 상장한 법인의 사업보고서(11011), 반기보고서(11012) 1분내 제출된 건 있으면 1번만 알람이 울리도록
        if (scwin.isExistedTodoJob2()) {
            if (scwin.alarmCnt % 2 == 0) {
                if (isDup && scwin.alarmCnt == 0) {
                    setTimeout("playAlarm(2)", 5000); //알림소리 겹치지 않게 5초 지연

                } else if (isDup && scwin.alarmCnt != 0) {
                    setTimeout("playAlarm(2)", 2000); //알림소리 겹치지 않게 2초 지연

                } else {
                    scwin.playAlarm(2);
                }
            }
        }
    }
};
scwin.playAlarm = function(n) {
    //		alertSound.play();
    eval("alertSound" + n).play();
};
scwin.isExistedTodoJob = function() {
    var tmpStatCd = "";
    for (i = dts_DsclApprovalList.getTotalRow(); i >= 1; i--) {
        tmpStatCd = dts_DsclApprovalList.getCellData(i, "DISCLS_PROCS_STAT_CD");
        //공시처리상태가 '승인','유보'가 아닌 건이 한건이라도 있으면 알림소리 true로 리턴.
        if ((tmpStatCd != "30") && (tmpStatCd != "40")) {
            return true;
        }
    }
    return false;
};
scwin.isExistedTodoJob2 = function() {
    var tmpFormCd = "";
    var tmpDiffMin = "";
    for (i = dts_DsclApprovalList.getTotalRow(); i >= 1; i--) {
        tmpFormCd = dts_DsclApprovalList.getCellData(i, "FORM_CD");
        tmpDiffMin = dts_DsclApprovalList.getCellData(i, "DIFF_MIN");
        //채권만 상장한 법인의 사업보고서(11011), 반기보고서(11012) 1분내 제출된 건 있으면 알림소리 true로 리턴.					
        if ((tmpFormCd == "11011" || tmpFormCd == "11012") && tmpDiffMin == "0") {
            return true;
        }
    }
    return false;
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        $c.stf.fn_OpenNoDisclViewer(scwin.gAcptNo, scwin.gViewerStat, js_emp_no, js_dep_cd, js_jobtitl, js_duty, js_duty_chrg, 'M', dts_DutyStatus); //2013.05.14
        //fn_OpenNoDisclViewer(gAcptNo, gViewerStat);

    } else if (colid == "ACPT_DDTM") {
        $c.stf.fn_OpenDisclAllList();
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.search_yn = true;
    fn_CheckCond('N');
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_DutyStatus_OnLoadError = function() {
    $c.stf.alert_error(dts_DutyStatus);
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    /*
    	setObjectValue(cmb_TeamList, js_dep_cd) ;	
    	// 부서코드 가져온후에  초기검색	
    	fn_InitSearch() ;
    */
    scwin.fn_DepListLoadComplete();
};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_EmpList, js_emp_no) ;	// 로그인사람을 디폴트 선택시

};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.dts_DsclApprovalList_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclApprovalList);


    /*
    var fFrame = frame.Provider("../").ActiveFrame.FrameID;
    var fname = frame.FrameID;
    if (fFrame == fname) {
    	CloseWin('', grd_Grid);
    }	*/

    $c.cm.CloseWin(0, grd_Grid);
    scwin.search_yn = false;
};
scwin.dts_DsclApprovalList_OnLoadCompleted = function(rowcount) {
    if (dts_DsclApprovalList.errorMsg) {
        $c.win.alert(dts_DsclApprovalList.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }

    /*
    var fFrame = frame.Provider("../").ActiveFrame.FrameID;
    var fname = frame.FrameID;
    if (fFrame == fname) {
    	CloseWin(rowcount, grd_Grid);
    }	*/

    $c.cm.CloseWin(rowcount, grd_Grid);
    scwin.search_yn = false;
    if (scwin.isBondsTeam) scwin.alarmCheck();
};
scwin.chb_stat_all_onclick = function() {
    scwin.fn_checkAll();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "책임자승인 목록", "", "2");
};
scwin.img_Cal_onclick = function() {
    popUpCalendar2(edt_SrchDay);
};
scwin.gform_onload = function() {
    // 리로드 시 스크립트 오류로 인해 패치함

    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();


    // 가우스헤더 셋팅
